package ua.empirecraft.feudal;

import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import static ua.empirecraft.feudal.CityMarketService.*;
import ua.empirecraft.feudal.FeudalService.Actor;

/** Durable city-to-city army commerce. Money and projection intents commit together in real SQL. */
public final class RecruitMarketService {
    public record Roster(String asset,String regiment,String groups,String town,String nation,String commander,String name,int count,String fingerprint,boolean eligible,boolean exclusive,boolean local) {
        public Roster(String asset,String regiment,String groups,String town,String nation,String commander,String name,int count,String fingerprint,boolean eligible,boolean exclusive){this(asset,regiment,groups,town,nation,commander,name,count,fingerprint,eligible,exclusive,true);}
    }
    public interface World {
        Roster roster(String asset);
        String home(String person);
        default boolean commander(String town,String person){return Objects.equals(town,home(person));}
        String nation(String town);
        boolean mayor(String person,String town);
        boolean republic(String town);
        boolean direct(String seller,String buyer);
        boolean safeCaptain(String person);
        boolean capacity(String nation,int incoming);
        String citizenship(String person);
    }
    final CityMarketService m;final FeudalService s;final Database db;final World world;
    private int offerCursor;
    public RecruitMarketService(CityMarketService markets,World world)throws SQLException {
        m=markets;s=m.s;db=s.db;this.world=world;
        for(String ddl:List.of(
            "CREATE TABLE IF NOT EXISTS rm_offers(id VARCHAR(36) PRIMARY KEY,asset VARCHAR(40),kind VARCHAR(8),regiment VARCHAR(36),groups CLOB,seller VARCHAR(80),nation VARCHAR(36),commander VARCHAR(36),name VARCHAR(96),soldiers INT,fingerprint VARCHAR(64),market VARCHAR(36),buyer VARCHAR(80),code VARCHAR(8),price BIGINT,seller_bps INT,created BIGINT,ends BIGINT,state VARCHAR(16))",
            "CREATE TABLE IF NOT EXISTS rm_locks(company VARCHAR(36) PRIMARY KEY,regiment VARCHAR(36),offer VARCHAR(36))",
            "CREATE TABLE IF NOT EXISTS rm_captains(person VARCHAR(36) PRIMARY KEY,contract VARCHAR(36))",
            "CREATE TABLE IF NOT EXISTS rm_battles(id VARCHAR(36) PRIMARY KEY,name VARCHAR(96),town_a VARCHAR(80),town_b VARCHAR(80),status VARCHAR(16),duration INT,created BIGINT,deadline BIGINT,started BIGINT DEFAULT 0,ends BIGINT DEFAULT 0,reason VARCHAR(1000) DEFAULT '')",
            "CREATE TABLE IF NOT EXISTS rm_contracts(id VARCHAR(36) PRIMARY KEY,offer VARCHAR(36),battle VARCHAR(36),buyer VARCHAR(80),commander VARCHAR(36),state VARCHAR(16),created BIGINT,consent_until BIGINT,buyer_bps INT,verdict VARCHAR(16) DEFAULT '',judge VARCHAR(80) DEFAULT '',reason VARCHAR(1000) DEFAULT '',citizenship CLOB)",
            "CREATE TABLE IF NOT EXISTS rm_jobs(seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset VARCHAR(40),kind VARCHAR(8),regiment VARCHAR(36),groups CLOB,town VARCHAR(80),nation VARCHAR(36),commander VARCHAR(36),contract VARCHAR(36),origin VARCHAR(80))",
            "CREATE INDEX IF NOT EXISTS rm_job_asset ON rm_jobs(asset,seq)",
            "CREATE INDEX IF NOT EXISTS rm_offer_state ON rm_offers(state,ends)",
            "CREATE INDEX IF NOT EXISTS rm_contract_battle ON rm_contracts(battle,state)"
        ))db.execute(ddl);
    }
    boolean mayor(Actor actor,String town)throws SQLException {return town!=null&&town.startsWith("t:")&&s.estate(town).active()&&actor.id().equals(s.estate(town).lord())&&world.mayor(actor.id(),town);}
    private void admin(Actor actor){require(actor.admin(),LocalText.tr("Потрібен адміністратор битв."));}
    public Map<String,Object> offer(String id)throws SQLException {var row=db.one("SELECT * FROM rm_offers WHERE id=?",id);require(row!=null,LocalText.tr("Пропозицію війська не знайдено."));return row;}
    public Map<String,Object> contract(String id)throws SQLException {var row=db.one("SELECT * FROM rm_contracts WHERE id=?",id);require(row!=null,LocalText.tr("Договір найманців не знайдено."));return row;}
    public Map<String,Object> battle(String id)throws SQLException {var row=db.one("SELECT * FROM rm_battles WHERE id=?",id);require(row!=null,LocalText.tr("Битву не знайдено."));return row;}
    static List<String> groups(String value){return Arrays.stream(value.split(",")).filter(x->!x.isBlank()).toList();}
    private void unlocked(Roster roster)throws SQLException {
        for(String group:groups(roster.groups))require(db.one("SELECT company FROM rm_locks WHERE company=?",group)==null,LocalText.tr("Військо вже зарезервоване для продажу або найму."));
        if(roster.asset.startsWith("R:"))require(db.one("SELECT company FROM rm_locks WHERE regiment=? LIMIT 1",roster.regiment)==null,LocalText.tr("У полку є зарезервований загін."));
    }
    private boolean marketplace(String market,String seller)throws SQLException {
        if(market.isBlank())return true;
        String host=string(m.market(market),"town");return m.open(market,Department.GOODS)&&(host.equals(seller)||world.republic(host));
    }
    public String list(Actor actor,String request,String asset,String kind,String market,Place place,String buyer,String code,long price,int hours){return m.once(actor,request,"recruits-list|"+List.of(asset,kind,market,buyer,code,""+price,""+hours),()->{
        require(Set.of("SALE","HIRE").contains(kind),LocalText.tr("Спосіб: SALE або HIRE."));
        require(asset.startsWith(kind.equals("SALE")?"R:":"C:"),LocalText.tr("Продається полк R:UUID, наймається загін C:UUID."));
        Roster roster=world.roster(asset);require(roster.eligible&&roster.count>0,LocalText.tr("Військо недоступне, утікає або має солдатів інших міст."));
        require(mayor(actor,roster.town),LocalText.tr("Виставляє військо мер міста-власника."));unlocked(roster);
        if(kind.equals("HIRE")){require(roster.local&&roster.town.equals(world.home(roster.commander)),LocalText.tr("Для найму на битву командир і бійці мають бути з міста-власника; союзне командування доступне без зміни громадянства."));require(roster.exclusive&&world.safeCaptain(roster.commander),LocalText.tr("Командир найманців не може бути мером, королем або командувати іншими солдатами."));}
        require(price>0&&price<=CurrencyService.MAX_MONEY&&hours>=1&&hours<=168,LocalText.tr("Ціна має бути додатною; строк продажу: 1–168 годин."));s.currency(code);
        int sellerBps=0;
        if(market.isBlank())require(!roster.town.equals(buyer)&&buyer.startsWith("t:")&&s.estate(buyer).active(),LocalText.tr("Виберіть інше місто-покупця."));
        else {require(buyer.isBlank()&&marketplace(market,roster.town),LocalText.tr("На звичайному базарі продають військо свого міста; чужі міста торгують у торговельній республіці."));m.access(market,Department.GOODS,place);m.payment(market,code);sellerBps=(int)number(m.tariff(market),"seller");}
        String id=id();db.execute("INSERT INTO rm_offers VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'OPEN')",id,asset,kind,roster.regiment,roster.groups,roster.town,roster.nation,roster.commander,roster.name,roster.count,roster.fingerprint,market,buyer,code,price,sellerBps,s.now(),s.now()+(market.isBlank()?300_000:hours*3_600_000L));
        for(String group:groups(roster.groups))db.execute("INSERT INTO rm_locks VALUES(?,?,?)",group,roster.regiment,id);
        s.audit(actor,"RECRUIT_LIST",id+" "+kind+" "+asset+" "+roster.town);return id;
    });}
    boolean valid(Map<String,Object> row)throws SQLException {
        String market=string(row,"market");if(!s.estate(string(row,"seller")).active()||!marketplace(market,string(row,"seller")))return false;
        if(!market.isBlank()){var permit=db.one("SELECT payment FROM cm_permits WHERE market=? AND code=?",market,string(row,"code"));if(permit==null||!bool(permit,"payment"))return false;}
        Roster current=world.roster(string(row,"asset"));
        return current!=null&&current.eligible&&current.fingerprint.equals(string(row,"fingerprint"))&&current.town.equals(string(row,"seller"))&&(!string(row,"kind").equals("HIRE")||current.local&&current.exclusive&&current.town.equals(world.home(current.commander))&&world.safeCaptain(current.commander));
    }
    public String stamp(String id)throws SQLException {
        var row=offer(id);String market=string(row,"market");var roster=world.roster(string(row,"asset"));
        require(roster!=null,LocalText.tr("Військо більше недоступне."));
        return hash(row.toString()+"|"+roster.fingerprint+"|"+(market.isBlank()?"":m.tariff(market).toString()+m.market(market).get("version")));
    }
    public record Purchase(Map<String,Object> offer,String nation,int buyerBps) {}
    public Purchase inspect(Actor actor,String id,String buyer,String commander,String battle,Place place,String expected)throws SQLException {
        var row=offer(id);require(stamp(id).equals(expected),LocalText.tr("Умови війська змінилися; перегляньте пропозицію повторно."));
        require(string(row,"state").equals("OPEN")&&number(row,"ends")>s.now()&&valid(row),LocalText.tr("Пропозиція війська вже недоступна."));access(actor,row,buyer,place);
        String nation=nation(buyer);require(world.capacity(nation,incoming(row,nation)),LocalText.tr("У нації покупця недостатньо місць у ліміті рекрутів."));
        if(string(row,"kind").equals("SALE"))require(battle.isBlank()&&world.commander(buyer,commander),LocalText.tr("Новий командир полку має жити в місті покупця або союзному місті."));
        else {var event=battle(battle);require(string(event,"status").equals("OPEN")&&number(event,"deadline")>s.now()&&(buyer.equals(string(event,"town_a"))||buyer.equals(string(event,"town_b"))),LocalText.tr("Найм доступний місту-учаснику до початку цієї битви."));
            require(db.one("SELECT person FROM rm_captains WHERE person=?",string(row,"commander"))==null,LocalText.tr("Командир уже має договір найманців."));}
        return new Purchase(row,nation,buyerFee(row));
    }
    private void access(Actor actor,Map<String,Object> row,String buyer,Place place)throws SQLException {
        require(mayor(actor,buyer)&&!buyer.equals(string(row,"seller")),LocalText.tr("Купівлю від іншого міста підтверджує його мер."));
        s.controlTreasury(actor,s.estate(buyer));
        String market=string(row,"market");
        if(market.isBlank()){require(buyer.equals(string(row,"buyer")),LocalText.tr("Пропозиція призначена іншому місту."));require(world.direct(string(row,"seller"),actor.id()),LocalText.tr("Для трейду мери обох міст мають стояти поруч."));}
        else {m.access(market,Department.GOODS,place);m.payment(market,string(row,"code"));}
    }
    private static String escrow(String id){return "m:recruit:"+id;}
    private int buyerFee(Map<String,Object> row)throws SQLException {String market=string(row,"market");return market.isBlank()?0:(int)number(m.tariff(market),"buyer");}
    private String nation(String town){String nation=world.nation(town);require(nation!=null&&!nation.isBlank(),LocalText.tr("Місто покупця має належати до нації Towny."));return nation;}
    private int incoming(Map<String,Object> row,String nation){return nation.equals(string(row,"nation"))?0:(int)number(row,"soldiers");}
    private void job(Map<String,Object> row,String kind,String town,String nation,String commander,String contract)throws SQLException {
        db.execute("INSERT INTO rm_jobs(asset,kind,regiment,groups,town,nation,commander,contract,origin) VALUES(?,?,?,?,?,?,?,?,?)",string(row,"asset"),kind,string(row,"regiment"),string(row,"groups"),town,nation,commander,contract,string(row,"seller"));
    }
    public String buy(Actor actor,String request,String id,String buyer,String commander,String battle,Place place,String expected){return m.once(actor,request,"recruits-buy|"+List.of(id,buyer,commander,battle,expected),()->{
        Purchase quote=inspect(actor,id,buyer,commander,battle,place,expected);var row=quote.offer();String nation=quote.nation();int bps=quote.buyerBps();String contract=id();
        if(string(row,"kind").equals("SALE")){
            require(battle.isBlank()&&world.commander(buyer,commander),LocalText.tr("Новий командир полку має жити в місті покупця або союзному місті."));
            m.move("e:"+buyer,escrow(id),string(row,"code"),Math.addExact(number(row,"price"),fee(number(row,"price"),bps)));
            payout(row,buyer,bps,true);job(row,"SALE",buyer,nation,commander,"");unlock(row);
            db.execute("UPDATE rm_offers SET state='SOLD',buyer=? WHERE id=?",buyer,id);
        } else {
            var event=battle(battle);require(string(event,"status").equals("OPEN")&&number(event,"deadline")>s.now()&&(buyer.equals(string(event,"town_a"))||buyer.equals(string(event,"town_b"))),LocalText.tr("Найм доступний місту-учаснику до початку цієї битви."));
            require(db.one("SELECT person FROM rm_captains WHERE person=?",string(row,"commander"))==null,LocalText.tr("Командир уже має договір найманців."));
            m.move("e:"+buyer,escrow(id),string(row,"code"),Math.addExact(number(row,"price"),fee(number(row,"price"),bps)));
            db.execute("INSERT INTO rm_contracts(id,offer,battle,buyer,commander,state,created,consent_until,buyer_bps,citizenship) VALUES(?,?,?,?,?,'RESERVED',?,?,?,?)",contract,id,battle,buyer,string(row,"commander"),s.now(),Math.min(number(event,"deadline"),s.now()+300_000),bps,"");
            db.execute("INSERT INTO rm_captains VALUES(?,?)",string(row,"commander"),contract);db.execute("UPDATE rm_offers SET state='RESERVED',buyer=? WHERE id=?",buyer,id);
            s.audit(actor,"MERCENARY_RESERVED",contract+" battle="+battle+" buyer="+buyer);
        }
        return string(row,"kind").equals("SALE")?id:contract;
    });}
    private void payout(Map<String,Object> row,String buyer,int buyerBps,boolean attended)throws SQLException {
        String id=string(row,"id"),code=string(row,"code");long held=s.balance(escrow(id),code);
        if(!attended){if(held>0)m.move(escrow(id),"e:"+buyer,code,held);return;}
        long price=number(row,"price"),sellerFee=fee(price,(int)number(row,"seller_bps")),buyFee=fee(price,buyerBps);
        require(held==Math.addExact(price,buyFee),LocalText.tr("Резерв оплати війська не відповідає договору."));
        m.move(escrow(id),"e:"+string(row,"seller"),code,price-sellerFee);
        if(sellerFee+buyFee>0)m.move(escrow(id),"e:"+string(m.market(string(row,"market")),"town"),code,sellerFee+buyFee);
    }
    private void unlock(Map<String,Object> offer)throws SQLException {db.execute("DELETE FROM rm_locks WHERE offer=?",string(offer,"id"));}
    public String consent(Actor actor,String request,String id,boolean accept){return m.once(actor,request,"mercenary-consent|"+id+accept,()->{
        var row=contract(id);require(string(row,"state").equals("RESERVED")&&number(row,"consent_until")>s.now(),LocalText.tr("Згода командира прострочена або вже надана."));
        require(actor.id().equals(string(row,"commander")),LocalText.tr("Згоду на найм дає лише командир цього загону."));
        var offer=offer(string(row,"offer"));require(Objects.equals(world.home(actor.id()),string(offer,"seller"))&&world.safeCaptain(actor.id()),LocalText.tr("Початкове місто або посада командира змінилися."));
        if(!accept){cancelContract(row,"Командир відхилив найм.");return id;}
        require(valid(offer),LocalText.tr("Склад або належність найманців змінилися."));
        db.execute("UPDATE rm_contracts SET state='WAITING' WHERE id=?",id);db.execute("UPDATE rm_offers SET state='WAITING' WHERE id=?",string(offer,"id"));s.audit(actor,"MERCENARY_CONSENT",id);return id;
    });}
    public String cancel(Actor actor,String request,String id){return m.once(actor,request,"recruit-cancel|"+id,()->{
        var contract=db.one("SELECT * FROM rm_contracts WHERE id=?",id);
        if(contract!=null){var offer=offer(string(contract,"offer"));require(Set.of("RESERVED","WAITING").contains(string(contract,"state")),LocalText.tr("Після початку битви договір завершується разом із нею."));
            require(actor.id().equals(string(contract,"commander"))||mayor(actor,string(contract,"buyer"))||mayor(actor,string(offer,"seller")),LocalText.tr("Це договір інших міст."));cancelContract(contract,"Сторона скасувала найм до битви.");return id;}
        var row=offer(id);require(string(row,"state").equals("OPEN")&&mayor(actor,string(row,"seller")),LocalText.tr("Скасувати відкритий продаж може мер міста-продавця."));
        db.execute("UPDATE rm_offers SET state='CANCELLED' WHERE id=?",id);unlock(row);s.audit(actor,"RECRUIT_CANCEL",id);return id;
    });}
    public String createBattle(Actor actor,String request,String name,String a,String b,int minutes){return m.once(actor,request,"battle-create|"+List.of(name,a,b,""+minutes),()->{
        admin(actor);require(name.length()>=1&&name.length()<=96&&!a.equals(b)&&a.startsWith("t:")&&b.startsWith("t:")&&s.estate(a).active()&&s.estate(b).active(),LocalText.tr("Укажіть назву та два різні активні міста."));nation(a);nation(b);require(minutes>=1&&minutes<=360,LocalText.tr("Тривалість битви: 1–360 хвилин."));
        String id=id();db.execute("INSERT INTO rm_battles(id,name,town_a,town_b,status,duration,created,deadline) VALUES(?,?,?,?,'OPEN',?,?,?)",id,name,a,b,minutes,s.now(),s.now()+FeudalService.DAY);s.audit(actor,"BATTLE_CREATE",id+" "+a+" "+b);return id;
    });}
    public String startBattle(Actor actor,String request,String id){return m.once(actor,request,"battle-start|"+id,()->{
        admin(actor);var event=battle(id);require(string(event,"status").equals("OPEN")&&number(event,"deadline")>s.now(),LocalText.tr("Битва вже почалася або строк підготовки минув."));
        for(var row:db.query("SELECT * FROM rm_contracts WHERE battle=? AND state='RESERVED'",id))cancelContract(row,"Командир не підтвердив найм до початку битви.");
        Map<String,Integer> totals=new HashMap<>();List<Map<String,Object>> accepted=new ArrayList<>();
        for(var row:db.query("SELECT * FROM rm_contracts WHERE battle=? AND state='WAITING' ORDER BY created,id",id)){
            var offer=offer(string(row,"offer"));String buyer=string(row,"buyer"),commander=string(row,"commander");
            if(!s.estate(buyer).active()||!valid(offer)||!string(offer,"seller").equals(world.home(commander))||!world.safeCaptain(commander)){cancelContract(row,"Умови найму змінилися до битви.");continue;}
            String nation=nation(buyer);totals.merge(nation,incoming(offer,nation),Integer::sum);accepted.add(row);
        }
        for(var total:totals.entrySet())require(world.capacity(total.getKey(),total.getValue()),LocalText.tr("У нації недостатньо місць для всіх найманців цієї битви."));
        db.execute("UPDATE rm_battles SET status='ACTIVE',started=?,ends=? WHERE id=?",s.now(),Math.addExact(s.now(),number(event,"duration")*60_000),id);
        for(var row:accepted){var offer=offer(string(row,"offer"));String commander=string(row,"commander");String saved=world.citizenship(commander);require(saved!=null&&!saved.isBlank(),LocalText.tr("Не вдалося зберегти початкове місто командира."));
            db.execute("UPDATE rm_contracts SET state='ACTIVE',citizenship=? WHERE id=?",saved,string(row,"id"));db.execute("UPDATE rm_offers SET state='ACTIVE' WHERE id=?",string(offer,"id"));
            job(offer,"HIRE",string(row,"buyer"),nation(string(row,"buyer")),commander,string(row,"id"));
        }
        s.audit(actor,"BATTLE_START",id+" contracts="+accepted.size());return id;
    });}
    public String verdict(Actor actor,String request,String id,boolean attended,String reason){return m.once(actor,request,"mercenary-verdict|"+List.of(id,""+attended,reason),()->{
        admin(actor);require(!reason.isBlank()&&reason.length()<=1000,LocalText.tr("Укажіть обґрунтування рішення адміністратора."));var row=contract(id);
        require(Set.of("ACTIVE","REVIEW").contains(string(row,"state")),LocalText.tr("Цей найм не очікує рішення про участь."));
        db.execute("UPDATE rm_contracts SET verdict=?,judge=?,reason=? WHERE id=?",attended?"PRESENT":"ABSENT",actor.id(),reason,id);s.audit(actor,"MERCENARY_VERDICT",id+" "+attended+" "+reason);
        if(string(row,"state").equals("REVIEW"))settle(contract(id));return id;
    });}
    public String endBattle(Actor actor,String request,String id,boolean cancelled,String reason){return m.once(actor,request,"battle-end|"+List.of(id,""+cancelled,reason),()->{
        admin(actor);require(!reason.isBlank()&&reason.length()<=1000,LocalText.tr("Укажіть причину завершення битви."));finish(battle(id),cancelled,reason);s.audit(actor,"BATTLE_END",id+" "+cancelled+" "+reason);return id;
    });}
    private void cancelContract(Map<String,Object> row,String reason)throws SQLException {
        if(!Set.of("RESERVED","WAITING").contains(string(row,"state")))return;var offer=offer(string(row,"offer"));payout(offer,string(row,"buyer"),(int)number(row,"buyer_bps"),false);
        db.execute("UPDATE rm_contracts SET state='REFUNDED',reason=? WHERE id=?",reason,string(row,"id"));db.execute("UPDATE rm_offers SET state='CANCELLED' WHERE id=?",string(offer,"id"));
        db.execute("DELETE FROM rm_captains WHERE contract=?",string(row,"id"));unlock(offer);s.audit(new Actor("mercenary-settlement",true),"MERCENARY_REFUND",string(row,"id")+" "+reason);
    }
    private void settle(Map<String,Object> row)throws SQLException {
        if(!string(row,"state").equals("REVIEW")||string(row,"verdict").isBlank())return;
        boolean attended=string(row,"verdict").equals("PRESENT");var offer=offer(string(row,"offer"));payout(offer,string(row,"buyer"),(int)number(row,"buyer_bps"),attended);
        db.execute("UPDATE rm_contracts SET state=? WHERE id=?",attended?"PAID":"REFUNDED",string(row,"id"));s.audit(new Actor("mercenary-settlement",true),attended?"MERCENARY_PAY":"MERCENARY_REFUND",string(row,"id"));
    }
    private void finish(Map<String,Object> event,boolean cancelled,String reason)throws SQLException {
        require(Set.of("OPEN","ACTIVE").contains(string(event,"status")),LocalText.tr("Битва вже завершена."));String id=string(event,"id");
        for(var row:db.query("SELECT * FROM rm_contracts WHERE battle=? AND state IN('RESERVED','WAITING','ACTIVE')",id)){
            if(!string(row,"state").equals("ACTIVE")){cancelContract(row,reason);continue;}
            var offer=offer(string(row,"offer"));job(offer,"RETURN",string(offer,"seller"),string(offer,"nation"),string(row,"commander"),string(row,"id"));
            db.execute("UPDATE rm_contracts SET state='REVIEW' WHERE id=?",string(row,"id"));db.execute("UPDATE rm_offers SET state='FINISHED' WHERE id=?",string(offer,"id"));
            if(cancelled)db.execute("UPDATE rm_contracts SET verdict='ABSENT',reason=? WHERE id=?",reason,string(row,"id"));
            // Keep company reservations until both citizenship and the native RETURN
            // projection are acknowledged. A delayed return must also block parent-regiment sales.
            settle(contract(string(row,"id")));
        }
        db.execute("UPDATE rm_battles SET status=?,ends=?,reason=? WHERE id=?",cancelled?"CANCELLED":"ENDED",s.now(),reason,id);
    }
    public void restored(String id){db.atomic(()->{var row=contract(id);if(Set.of("REVIEW","PAID","REFUNDED").contains(string(row,"state"))){unlock(offer(string(row,"offer")));db.execute("DELETE FROM rm_captains WHERE contract=?",id);}return null;});}
    public List<Map<String,Object>> citizenships()throws SQLException {return db.query("SELECT c.*,o.seller FROM rm_contracts c JOIN rm_offers o ON o.id=c.offer JOIN rm_captains p ON p.contract=c.id WHERE c.state IN('ACTIVE','REVIEW','PAID','REFUNDED') ORDER BY c.created");}
    public boolean citizenLocked(String person)throws SQLException {return db.one("SELECT p.person FROM rm_captains p JOIN rm_contracts c ON c.id=p.contract WHERE p.person=? AND c.state IN('ACTIVE','REVIEW','PAID','REFUNDED')",person)!=null;}
    public boolean cityLocked(String town)throws SQLException {return db.one("SELECT c.id FROM rm_contracts c JOIN rm_offers o ON o.id=c.offer JOIN rm_captains p ON p.contract=c.id WHERE (o.seller=? OR c.buyer=?) AND c.state IN('ACTIVE','REVIEW','PAID','REFUNDED') LIMIT 1",town,town)!=null;}
    public Map<String,Object> state()throws SQLException {
        List<Map<String,Object>> locks=new ArrayList<>();for(var row:db.query("SELECT id,regiment,groups,state FROM rm_offers WHERE state IN('OPEN','RESERVED','WAITING')"))locks.add(row);
        return Map.of("ready",true,"locks",locks,"jobs",db.query("SELECT j.* FROM rm_jobs j WHERE j.seq=(SELECT MAX(k.seq) FROM rm_jobs k WHERE k.asset=j.asset) ORDER BY j.seq"));
    }
    public void tick(){db.atomic(()->{
        for(var event:db.query("SELECT * FROM rm_battles WHERE status='OPEN' AND deadline<=? OR status='ACTIVE' AND ends<=?",s.now(),s.now()))finish(event,string(event,"status").equals("OPEN"),"Строк битви завершився.");
        for(var row:db.query("SELECT * FROM rm_contracts WHERE state='RESERVED' AND consent_until<=?",s.now()))cancelContract(row,"Командир не підтвердив найм вчасно.");
        for(var row:db.query("SELECT * FROM rm_offers WHERE state='OPEN' AND ends<=? ORDER BY ends LIMIT 500",s.now())){db.execute("UPDATE rm_offers SET state='EXPIRED' WHERE id=?",string(row,"id"));unlock(row);}
        var offers=db.query("SELECT * FROM rm_offers WHERE state='OPEN' AND ends>? ORDER BY created,id LIMIT 64 OFFSET ?",s.now(),offerCursor);
        for(var row:offers){
            boolean expired=number(row,"ends")<=s.now();if(!expired)try{expired=!valid(row);}catch(IllegalStateException unavailable){continue;}
            if(expired){db.execute("UPDATE rm_offers SET state='EXPIRED' WHERE id=?",string(row,"id"));unlock(row);}
        }
        offerCursor=offers.size()<64?0:offerCursor+64;
        return null;
    });}
}
